var buildOnce sync.Once
var cached Analysis
var cachedErr error

func BuildDefault() (Analysis, error) {
	buildOnce.Do(func() {
		inh := inherit()
		ledger := buildGeneratorLedger()
		closures := auditClosures()
		selectors := auditSelectors(closures)
		impact := auditImpact(closures, selectors)
		firewall := auditFirewall(impact)
		next := nextStep(closures, impact)
		cached = Analysis{Inheritance: inh, Ledger: ledger, Closures: closures, Selectors: selectors, Impact: impact, Firewall: firewall, Next: next}
		cached.Truth = truth(cached)
	})
	return cached, cachedErr
}

func inherit() Inheritance {
	return Inheritance{
		Executed:                         true,
		Gate399QuaternionicModuleAudited: true,
		Gate400PairDegenerateResponse:    true,
		Gate404CanonicalEdgeQuotient:     true,
		Gate406Q4ContactOnly:             true,
		Gate406Q4NotHphiSelector:         true,
		Gate372ChargedModuliDim:          Gate372ChargedModuliDim,
		NoEmpiricalInputsImported:        true,
		Verdict:                          StatusGate406Inherited,
	}
}

