func auditClosures() []AlgebraClosure {
	I := identity4()
	Li, Lj, Lk := leftI(), leftJ(), leftK()
	Ri, Rj, Rk := rightI(), rightJ(), rightK()
	S := scalarResponseMatrix()

	observable := closureRank([]Matrix4{I, Li, S})
	left := closureRank([]Matrix4{I, Li, Lj, Lk, S})
	full := closureRank([]Matrix4{I, Li, Lj, Lk, Ri, Rj, Rk, S})

	return []AlgebraClosure{
		{
			Name:                         "pair-compatible observable scalar subalgebra",
			Generators:                   []string{"I_4", "L_i/R_i-compatible complex structure", "S_phi", "canonical Q_Y edge quotient"},
			Dimension:                    observable,
			FullEndRHphi:                 false,
			Commutative:                  true,
			ContainsNoncommutingPairs:    false,
			PairDegeneracyClosed:         true,
			GenericNondegenerateCapacity: false,
			CanonicalSelectorSelected:    false,
			RequiresCoefficientChoice:    false,
			MinimalPolynomialCapacity:    "degree <= 2 for selected self-adjoint scalar observables",
			CharacteristicCapacity:       "pair-degenerate: (x-a)^2(x-b)^2",
			Verdict:                      StatusObservableSubalgebraPairClosed,
		},
		{
			Name:                         "left quaternionic action plus scalar response",
			Generators:                   []string{"I_4", "L_i", "L_j", "L_k", "S_phi"},
			Dimension:                    left,
			FullEndRHphi:                 false,
			Commutative:                  false,
			ContainsNoncommutingPairs:    true,
			PairDegeneracyClosed:         false,
			GenericNondegenerateCapacity: true,
			CanonicalSelectorSelected:    false,
			RequiresCoefficientChoice:    true,
			MinimalPolynomialCapacity:    "can exceed degree 2 after noncommuting compositions, but no selected element is derived",
			CharacteristicCapacity:       "non-pair capacity exists in generated algebra; selector coefficients are not native",
			Verdict:                      StatusFailedGenericAnisotropyNeedsCoeffs,
		},
		{
			Name:                         "full left/right quaternionic H_phi algebra plus scalar response",
			Generators:                   []string{"I_4", "L_i", "L_j", "L_k", "R_i", "R_j", "R_k", "S_phi"},
			Dimension:                    full,
			FullEndRHphi:                 full == 16,
			Commutative:                  false,
			ContainsNoncommutingPairs:    true,
			PairDegeneracyClosed:         false,
			GenericNondegenerateCapacity: full == 16,
			CanonicalSelectorSelected:    false,
			RequiresCoefficientChoice:    true,
			MinimalPolynomialCapacity:    "generic degree-4 capacity because the generated algebra is End_R(H_phi)",
			CharacteristicCapacity:       "four-distinct-root capacity exists only after choosing coefficients inside the full algebra",
			Verdict:                      StatusFullAlgebraCapacityFound,
		},
	}
}

