func auditImpact(closures []AlgebraClosure, selectors []SelectorCandidate) ModuliImpact {
	fullCapacity := false
	nativeSelected := false
	for _, c := range closures {
		if c.GenericNondegenerateCapacity {
			fullCapacity = true
		}
		if c.CanonicalSelectorSelected {
			nativeSelected = true
		}
	}
	for _, s := range selectors {
		if s.Native && s.Canonical && s.DistinctEigenvalueCapacity && !s.UsesArbitraryCoefficients {
			nativeSelected = true
		}
	}
	return ModuliImpact{
		ChargedModuliStart:               Gate372ChargedModuliDim,
		ChargedModuliResult:              Gate372ChargedModuliDim,
		NativeSelectorDerived:            nativeSelected,
		FullAlgebraNondegenerateCapacity: fullCapacity,
		CanonicalFlavorTextureDerived:    false,
		YukawaCouplingsReduced:           false,
		CKMCapacityDerived:               false,
		ScalarSectorFlavorBlind:          true,
		FlavorFirewallPreserved:          true,
		Verdict:                          StatusFirewallPreserved13Moduli,
	}
}

func auditFirewall(i ModuliImpact) FirewallAudit {
	return FirewallAudit{
		Executed:                       true,
		NoObservedMassesImported:       true,
		NoCKMImported:                  true,
		NoPMNSImported:                 true,
		NoYukawaAmplitudesInserted:     true,
		NoQ4HphiForcing:                true,
		NoArbitraryCoefficientPromoted: !i.NativeSelectorDerived,
		NoGenericMatrixPromoted:        !i.NativeSelectorDerived,
		NoFlavorModuliReductionClaimed: !i.YukawaCouplingsReduced && i.ChargedModuliResult == Gate372ChargedModuliDim,
		Verdict:                        StatusFirewallPreserved13Moduli,
	}
}

